/** Verifica las invariantes del derangement sobre el resultado del sorteo. */
function esperarDerangement(participantes: Participante[], asignaciones: NonNullable<ReturnType<typeof sortearAmigoSecreto>>) {
  // El mismo orden de "de" que la lista original.
  expect(asignaciones.map((a) => a.de)).toEqual(participantes);

  // Nadie se asigna a sí mismo.
  for (const { de, para } of asignaciones) {
    expect(de).not.toBe(para);
    expect(para).toBeOneOf(participantes);
  }

  // Todos regalan exactamente una vez...
  const regalando = asignaciones.map((a) => a.de.nombre).sort();
