}));

import { createTransport, type Transporter } from "nodemailer";
import type { Asignacion } from "@/lib/sorteo";

/** Con el cache del transporte invalidado, figuras importadas la magia de nuevo. */
async function importarMailer() {
  vi.resetModules();
  const modulo = await import("@/lib/mailer");
  transportesCreados = vi.mocked(createTransport).mock.results;
  return modulo;
}

let transportesCreados: Array<{
  type: string;
  value: Transporter;
}> = [];

/** El transporte creado por la última importación (siempre el único). */
function transporte(): { sendMail: typeof mocks.sendMail } {
  const created = transportesCreados.at(-1);
  return created!.value as unknown as { sendMail: typeof mocks.sendMail };
}

function asignacionesDeEjemplo(): Asignacion[] {
